<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Promotion;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class PromotionController extends Controller{public function index(){return view('admin.promotions.index',['promotions'=>Promotion::latest()->paginate(20)]);}public function store(Request $r){Promotion::create($this->data($r));return back()->with('success','Promotion created.');}public function update(Request $r,Promotion $promotion){$promotion->update($this->data($r,$promotion));return back()->with('success','Promotion updated.');}public function destroy(Promotion $promotion){$promotion->delete();return back()->with('success','Promotion deleted.');}private function data(Request $r,?Promotion $p=null){$d=$r->validate(['name'=>'required|string|max:150','code'=>['nullable','string','max:60',Rule::unique('promotions','code')->ignore($p?->id)],'type'=>'required|in:percentage,fixed,free_shipping','value'=>'required|numeric|min:0','minimum_order'=>'nullable|numeric|min:0','maximum_discount'=>'nullable|numeric|min:0','usage_limit'=>'nullable|integer|min:1','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','status'=>'nullable|boolean']);$d['status']=$r->boolean('status');return $d;}}

